-- Restore A Little Patience (map 1104, scenario 183).
-- Spawn, template-state, dialogue, and script binding data were ported read-only
-- from Legends of Azeroth Pandaria 5.4.8 (build 18414).
-- Legion build 26972 DB2 confirms scenario 183, difficulty 12, Alliance LFG 589,
-- Horde LFG 619, and the two criteria trees used by the adapted C++ scripts.
START TRANSACTION;

-- Replace any partial population with one coherent source population.
DELETE `ca` FROM `creature_addon` `ca` INNER JOIN `creature` `c` ON `c`.`guid`=`ca`.`guid` WHERE `c`.`map`=1104;
DELETE `wp` FROM `waypoint_data` `wp` INNER JOIN `creature` `c` ON `c`.`guid`=`wp`.`id` WHERE `c`.`map`=1104;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`memberGUID` WHERE `c`.`map`=1104;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`leaderGUID` WHERE `c`.`map`=1104;
DELETE `gec` FROM `game_event_creature` `gec` INNER JOIN `creature` `c` ON `c`.`guid`=`gec`.`guid` WHERE `c`.`map`=1104;
DELETE `pc` FROM `pool_creature` `pc` INNER JOIN `creature` `c` ON `c`.`guid`=`pc`.`guid` WHERE `c`.`map`=1104;
DELETE `geg` FROM `game_event_gameobject` `geg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`geg`.`guid` WHERE `go`.`map`=1104;
DELETE `pg` FROM `pool_gameobject` `pg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`pg`.`guid` WHERE `go`.`map`=1104;
DELETE FROM `creature` WHERE `map`=1104;
DELETE FROM `gameobject` WHERE `map`=1104;



