-- SpellScript bindings required by construction bars and Scargash mechanics.
DELETE FROM `spell_script_names` WHERE `spell_id` IN (133311,133461,133494,133849,133852,133928,134086,134116,134567,134959,134974,135260,135414) OR `ScriptName` IN ('spell_little_patience_faction_construction_progress','spell_little_patience_inspired_jinyu','spell_little_patience_terrified','spell_little_patience_construction_bar_movement','spell_little_patience_inspired_gnome','spell_little_patience_inspired_dwarf','spell_little_patience_blood_rage','spell_little_patience_blood_rage_fixate','spell_little_patience_inspired_night_elf');

